/**
 * The model registry and the downloader (models.ts). Nothing here touches the network: the
 * downloader is pointed at a loopback server serving generated bytes, and the guard that keeps
 * tests and CI from fetching a real model is itself tested.
 */

import { afterEach, describe, expect, test } from "bun:test";
import { createHash } from "node:crypto";
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  statSync,
  utimesSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { LIVE_ENGINES } from "../src/main/asr/live-engines.ts";
import { SCORES } from "../src/main/asr/model-scores.ts";
import { MODEL_TEXT } from "../src/main/asr/model-text.ts";
import {
  type CatalogEntry,
  ChecksumError,
  catalogProblems,
  DownloadRefused,
  defaultModelsDir,
  downloadFile,
  downloadModels,
  hostPlatform,
  MODELS,
  type ModelSpecEntry,
  modelFile,
  modelsFor,
  NEMOTRON,
  NEMOTRON_FILE,
  networkForbidden,
  pruneRetiredModels,
  RECOGNIZER,
  RETIRED_MODELS,
  verifyModels,
} from "../src/main/asr/models.ts";
import { recognizerConfig, SherpaRecognizer, writeBpeVocab } from "../src/main/asr/sherpa.ts";
import { tempDir } from "./helpers.ts";

/** The other chunk sizes of the streaming Nemotrons, in the catalog's order. */
const TIERS = [
  "nemotron-en-80",
  "nemotron-en-160",
  "nemotron-en-1120",
  "nemotron-3.5-80",
  "nemotron-3.5-160",
  "nemotron-3.5-320",
];

const cleanups: (() => void)[] = [];
afterEach(() => {
  for (const c of cleanups.splice(0)) c();
});

function dir(): string {
  const t = tempDir();
  cleanups.push(t.cleanup);
  return t.dir;
}

const sha = (b: Uint8Array) => createHash("sha256").update(b).digest("hex");

/** A loopback server for one file, recording the Range headers it saw; can cut a body short. */
function serve(body: Uint8Array, o: { cutAt?: number; ignoreRange?: boolean } = {}) {
  const ranges: (string | null)[] = [];
  let cut = o.cutAt;
  const server = Bun.serve({
    port: 0,
    hostname: "127.0.0.1",
    fetch(req) {
      const range = req.headers.get("range");
      ranges.push(range);
      let from = 0;
      if (range && !o.ignoreRange) from = Number(/bytes=(\d+)-/.exec(range)?.[1] ?? 0);
      let slice = body.subarray(from);
      if (cut !== undefined) {
        slice = slice.subarray(0, cut);
        cut = undefined;
      }
      return new Response(slice, { status: from > 0 ? 206 : 200 });
    },
  });
  cleanups.push(() => server.stop(true));
  return { url: `http://127.0.0.1:${server.port}/model.onnx`, ranges };
}

describe("the registry", () => {
  test("every file has an https URL pinned to a revision, a SHA-256, a size and a licence", () => {
    // The five sherpa and helper models, then on demand the three streaming Nemotron models of
    // the live path, Qwen and its llama-server builds (asr-llama.test.ts).
    expect(MODELS.filter((m) => !m.onDemand).map((m) => m.id)).toEqual([
      RECOGNIZER,
      "silero-vad",
      NEMOTRON,
      "pyannote-segmentation-3.0",
      "titanet-small",
    ]);
    expect(
      MODELS.filter((m) => m.onDemand)
        .slice(0, 10)
        .map((m) => m.id),
    ).toEqual([
      "nemotron-en-560",
      "nemotron-3.5-560",
      "nemotron-3.5-1120",
      ...TIERS,
      "qwen3-asr-1.7b",
    ]);
    for (const m of MODELS) {
      expect(m.licence).toMatch(
        /^(MIT|CC-BY-4\.0|Apache-2\.0|OpenMDW-1\.1|NVIDIA Open Model License)$/,
      );
      expect(m.source).toMatch(/^https:\/\//);
      for (const f of m.files) {
        expect(f.url).toMatch(/^https:\/\//);
        expect(f.url).not.toMatch(/\/(main|master|latest)\//);
        expect(f.sha256).toMatch(/^[0-9a-f]{64}$/);
        expect(f.size).toBeGreaterThan(0);
      }
    }
    // The recognizer ships its tokenizer, from which biasing builds its bpe.vocab.
    const names = MODELS[0]?.files.map((f) => f.name);
    expect(names).toContain("tokenizer.json");
    expect(names).toContain("tokens.txt");
  });

  test("each other chunk size of a streaming Nemotron runs as the 560 ms tier does: its own encoder, the same rest, a live engine row, a name and a line, and no score anyone guessed", () => {
    /** What is wrong with a tier entry, against the 560 ms tier of its family; empty when whole. */
    const problems = (m: CatalogEntry, engines: Record<string, { tierMs: number }>): string[] => {
      const out: string[] = [];
      const [, family, ms] = /^nemotron-(en|3\.5)-(\d+)$/.exec(m.id) ?? [];
      if (!family || !ms) return [`${m.id}: not a tier id`];
      const base = MODELS.find((x) => x.id === `nemotron-${family}-560`) as CatalogEntry;
      if (m.files.map((f) => f.name).join() !== base.files.map((f) => f.name).join())
        out.push("files differ from the 560 ms tier's");
      for (const f of m.files) {
        if (!f.url.includes(`-${ms}ms-int8-`))
          out.push(`${f.name}: url is not the ${ms} ms export`);
        if (!/\/resolve\/[0-9a-f]{40}\//.test(f.url)) out.push(`${f.name}: url not pinned`);
        const same = base.files.find((b) => b.name === f.name);
        if (f.name === "encoder.int8.onnx") {
          if (same?.sha256 === f.sha256) out.push("encoder is the 560 ms tier's");
        } else if (same?.sha256 !== f.sha256 || same?.size !== f.size)
          out.push(`${f.name}: not the shared file`);
      }
      if (engines[m.id]?.tierMs !== Number(ms)) out.push("no live engine row with its chunk");
      if (m.licence !== base.licence || m.source !== base.source) out.push("licence or source");
      if (JSON.stringify(m.languages) !== JSON.stringify(base.languages)) out.push("languages");
      if (!m.onDemand || m.serves.join() !== "live") out.push("not an on-demand live model");
      if (!MODEL_TEXT[m.id]?.name || !MODEL_TEXT[m.id]?.lines.live) out.push("no name or line");
      const sc = SCORES[m.id];
      if (!sc || !("notMeasured" in sc.accuracy) || !("notMeasured" in sc.speed))
        out.push("a score nobody measured");
      return out;
    };
    const tiers = MODELS.filter((m) => TIERS.includes(m.id));
    expect(tiers.map((m) => m.id)).toEqual(TIERS);
    for (const m of tiers)
      expect(`${m.id}: ${problems(m, LIVE_ENGINES).join("; ")}`).toBe(`${m.id}: `);
    expect(catalogProblems(MODELS)).toEqual([]);
    // Every encoder is its own file.
    expect(new Set(tiers.map((m) => m.files[0]?.sha256)).size).toBe(tiers.length);
    // Positive control: a tier whose engine row has the wrong chunk, or a shared file that is not
    // the shared one, is caught.
    const one = tiers[0] as CatalogEntry;
    expect(problems(one, { ...LIVE_ENGINES, [one.id]: { tierMs: 560 } })).toContain(
      "no live engine row with its chunk",
    );
    const bent = {
      ...one,
      files: one.files.map((f) => (f.name === "joiner.int8.onnx" ? { ...f, size: 1 } : f)),
    };
    expect(problems(bent, LIVE_ENGINES)).toContain("joiner.int8.onnx: not the shared file");
  });

  test("Nemotron is the 400 MB ONNX export pinned to a revision, under NVIDIA's OpenMDW licence", () => {
    const m = MODELS.find((x) => x.id === NEMOTRON);
    expect(m?.licence).toBe("OpenMDW-1.1");
    expect(m?.source).toBe("https://huggingface.co/nvidia/Nemotron-3-Diarization");
    expect(m?.files).toEqual([
      {
        name: NEMOTRON_FILE,
        url: expect.stringMatching(/\/resolve\/[0-9a-f]{40}\/nemotron-3-diarization\//),
        sha256: "915e4fa23b0192ed9fadeb1cdd26847df986d50c92012d177be28d0343bbe03a",
        size: 400506656,
      },
    ]);
  });

  test("the diarize CI job smokes the same Nemotron file the registry pins", () => {
    const pin = (yml: string) => ({
      url: /^\s*MODEL_URL:\s*(\S+)\s*$/m.exec(yml)?.[1],
      sha256: /^\s*MODEL_SHA256:\s*(\S+)\s*$/m.exec(yml)?.[1],
    });
    const f = MODELS.find((x) => x.id === NEMOTRON)?.files[0];
    // The PR smoke (ci.yml) and the nightly evaluation (nightly.yml) both fetch it.
    for (const wf of ["ci.yml", "nightly.yml"]) {
      const text = readFileSync(join(import.meta.dir, "..", ".github", "workflows", wf), "utf8");
      expect({ wf, ...pin(text) }).toEqual({ wf, url: f?.url, sha256: f?.sha256 });
    }
    const yml = readFileSync(join(import.meta.dir, "..", ".github", "workflows", "ci.yml"), "utf8");
    // Positive control: a pin bumped on one side only is caught.
    const bumped = yml.replace(f?.sha256 as string, "0".repeat(64));
    expect(pin(bumped)).not.toEqual({ url: f?.url, sha256: f?.sha256 });
  });

  test("a machine downloads only what its asr.diarizer needs", () => {
    const ids = (k: "nemotron" | "embeddings") =>
      modelsFor({ "asr.diarizer": k }, hostPlatform()).map((m) => m.id);
    // TitaNet stays with Nemotron: it carries names across a stream that starts over.
    expect(ids("nemotron")).toEqual([RECOGNIZER, "silero-vad", NEMOTRON, "titanet-small"]);
    expect(ids("embeddings")).toEqual([
      RECOGNIZER,
      "silero-vad",
      "pyannote-segmentation-3.0",
      "titanet-small",
    ]);
    // Every model is needed by one choice or the other: none is fetched for nothing. The on-demand
    // entries (Qwen and its runtime) come only when a job or a pull names them.
    const used = new Set([...ids("nemotron"), ...ids("embeddings")]);
    expect(MODELS.filter((m) => !m.onDemand).every((m) => used.has(m.id))).toBe(true);
    expect(MODELS.filter((m) => m.onDemand).some((m) => used.has(m.id))).toBe(false);
  });

  test("a retired model is never a current one, and pruning removes only the retired folders", () => {
    const current = new Set(MODELS.map((m) => m.id));
    expect(RETIRED_MODELS.length).toBeGreaterThan(0);
    for (const id of RETIRED_MODELS) expect(current.has(id)).toBe(false);
    const d = dir();
    for (const id of [...RETIRED_MODELS, RECOGNIZER, "mine"]) {
      mkdirSync(join(d, id), { recursive: true });
      writeFileSync(join(d, id, "f.onnx"), "x");
    }
    expect(pruneRetiredModels(d)).toEqual([...RETIRED_MODELS]);
    for (const id of RETIRED_MODELS) expect(existsSync(join(d, id))).toBe(false);
    expect(existsSync(join(d, RECOGNIZER, "f.onnx"))).toBe(true);
    expect(existsSync(join(d, "mine", "f.onnx"))).toBe(true);
    // Nothing left to remove the second time.
    expect(pruneRetiredModels(d)).toEqual([]);
  });

  test("the models folder is per user and AKOU_MODELS_DIR overrides it", () => {
    expect(defaultModelsDir({ AKOU_MODELS_DIR: "/x/models" }, "linux")).toBe("/x/models");
    expect(defaultModelsDir({ XDG_DATA_HOME: "/d" }, "linux")).toBe(join("/d", "akou", "models"));
    expect(defaultModelsDir({}, "darwin")).toContain(join("Application Support", "akou", "models"));
  });
});

describe("tests and CI never download", () => {
  test("under bun test the guard is on", () => {
    expect(networkForbidden()).toBe(true);
    expect(networkForbidden({ CI: "true" })).toBe(true);
    expect(networkForbidden({})).toBe(false);
  });

  test("a real model URL is refused before any request is made", async () => {
    let fetched = false;
    const f = MODELS[1]?.files[0];
    if (!f) throw new Error("no file");
    const err = await downloadFile("silero-vad", f, join(dir(), "x.onnx"), {
      fetch: (async () => {
        fetched = true;
        return new Response("");
      }) as unknown as typeof fetch,
    }).catch((e) => e);
    expect(err).toBeInstanceOf(DownloadRefused);
    expect(fetched).toBe(false);
  });
});

describe("the downloader", () => {
  const body = new Uint8Array(200_000).map((_, i) => (i * 31) % 251);
  const spec = (url: string, over: Partial<{ sha256: string; size: number }> = {}) => ({
    name: "model.onnx",
    url,
    sha256: sha(body),
    size: body.length,
    ...over,
  });

  test("a file is moved into place only after its SHA-256 matches", async () => {
    const s = serve(body);
    const path = join(dir(), "m", "model.onnx");
    await downloadFile("m", spec(s.url), path);
    expect(sha(new Uint8Array(readFileSync(path)))).toBe(sha(body));
    expect(existsSync(`${path}.part`)).toBe(false);
  });

  test("an interrupted download resumes from the .part file with a Range request", async () => {
    const s = serve(body, { cutAt: 50_000 });
    const path = join(dir(), "model.onnx");
    // The first attempt gets a short body and fails the check, keeping nothing half-verified.
    await expect(downloadFile("m", spec(s.url), path)).rejects.toBeInstanceOf(ChecksumError);
    expect(existsSync(path)).toBe(false);
    // A partial file left by a crash is resumed, not refetched.
    writeFileSync(`${path}.part`, body.subarray(0, 120_000));
    await downloadFile("m", spec(s.url), path);
    expect(s.ranges.at(-1)).toBe("bytes=120000-");
    expect(statSync(path).size).toBe(body.length);
  });

  test("a server that ignores the range restarts the file instead of corrupting it", async () => {
    const s = serve(body, { ignoreRange: true });
    const path = join(dir(), "model.onnx");
    writeFileSync(`${path}.part`, body.subarray(0, 1000));
    await downloadFile("m", spec(s.url), path);
    expect(sha(new Uint8Array(readFileSync(path)))).toBe(sha(body));
  });

  test("a checksum mismatch deletes the partial file and throws", async () => {
    const s = serve(body);
    const path = join(dir(), "model.onnx");
    const err = await downloadFile("m", spec(s.url, { sha256: "0".repeat(64) }), path).catch(
      (e) => e,
    );
    expect(err).toBeInstanceOf(ChecksumError);
    expect(String(err.message)).toContain("does not match the pinned");
    expect(existsSync(path)).toBe(false);
    expect(existsSync(`${path}.part`)).toBe(false);
  });

  test("downloadModels skips verified files and verifyModels reports each state", async () => {
    const s = serve(body);
    const d = dir();
    const registry: ModelSpecEntry[] = [
      { id: "m", job: "test", licence: "MIT", source: "https://example.org", files: [spec(s.url)] },
    ];
    await downloadModels(d, ["m"], { registry });
    const before = s.ranges.length;
    await downloadModels(d, ["m"], { registry });
    expect(s.ranges.length).toBe(before);

    const real = dir();
    const states = await verifyModels(real, ["silero-vad"]);
    expect(states).toEqual([
      {
        model: "silero-vad",
        name: "silero_vad.onnx",
        path: modelFile(real, "silero-vad", "silero_vad.onnx"),
        state: "missing",
      },
    ]);
    mkdirSync(join(real, "silero-vad"), { recursive: true });
    writeFileSync(modelFile(real, "silero-vad", "silero_vad.onnx"), "not a model");
    expect((await verifyModels(real, ["silero-vad"]))[0]?.state).toBe("size");
  });
});

describe("[spike] Hotwords to a non-transducer model kill the process: the sherpa-onnx guard", () => {
  // A stub in place of the native recognizer: the guard must refuse before any stream exists.
  function stub() {
    const calls: unknown[][] = [];
    const rec = {
      createStream: (...args: unknown[]) => {
        calls.push(args);
        return { acceptWaveform: () => {} };
      },
      decode: () => {},
      getResult: () => ({ text: " ok " }),
    };
    return { rec, calls };
  }
  const audio = new Float32Array(16000);

  test("an empty hotword string and any hotwords to a non-transducer throw before createStream", () => {
    const a = stub();
    const parakeet = new SherpaRecognizer(RECOGNIZER, a.rec, "beam");
    expect(() => parakeet.decode(audio, "")).toThrow(/refusing hotwords/);
    const b = stub();
    const moonshine = new SherpaRecognizer("moonshine-base", b.rec, "beam");
    expect(moonshine.kind).not.toBe("transducer");
    expect(() => moonshine.decode(audio, "Hetzner")).toThrow(/refusing hotwords/);
    expect([...a.calls, ...b.calls]).toEqual([]);
  });

  test("positive control: a transducer with hotwords, and any model without, reach createStream", () => {
    const a = stub();
    const parakeet = new SherpaRecognizer(RECOGNIZER, a.rec, "beam");
    expect(parakeet.decode(audio, "Hetzner").text).toBe("ok");
    expect(parakeet.decode(audio).text).toBe("ok");
    const b = stub();
    new SherpaRecognizer("moonshine-base", b.rec, "beam").decode(audio);
    expect(a.calls).toEqual([["Hetzner"], []]);
    expect(b.calls).toEqual([[]]);
  });
});

describe("Parakeet decodes greedy; hotwords only with beam, at 1.5 (asr.parakeet.decoding)", () => {
  const file = (name: string) => `/m/${name}`;

  test("greedy: greedy_search, no hotword score, no bpe.vocab", () => {
    const c = recognizerConfig(file, 2, { decoding: "greedy" });
    expect(c.decodingMethod).toBe("greedy_search");
    expect(c).not.toHaveProperty("hotwordsScore");
    expect(c).not.toHaveProperty("maxActivePaths");
    expect(c.modelConfig).not.toHaveProperty("bpeVocab");
    expect(c.modelConfig).not.toHaveProperty("modelingUnit");
    expect(c.modelConfig).toMatchObject({ tokens: "/m/tokens.txt", numThreads: 2 });
  });

  test("beam: modified_beam_search with the bpe.vocab and hotwords at 1.5", () => {
    const c = recognizerConfig(file, 4, { decoding: "beam", bpeVocab: "/c/bpe-x.vocab" });
    expect(c.decodingMethod).toBe("modified_beam_search");
    expect(c.hotwordsScore).toBe(1.5);
    expect(c.maxActivePaths).toBe(4);
    expect(c.modelConfig).toMatchObject({
      modelingUnit: "bpe",
      bpeVocab: "/c/bpe-x.vocab",
      numThreads: 4,
    });
  });

  test("a greedy recognizer refuses hotwords before createStream, and decodes without them", () => {
    const calls: unknown[][] = [];
    const rec = {
      createStream: (...args: unknown[]) => {
        calls.push(args);
        return { acceptWaveform: () => {} };
      },
      decode: () => {},
      getResult: () => ({ text: " ok " }),
    };
    const greedy = new SherpaRecognizer(RECOGNIZER, rec, "greedy");
    expect(() => greedy.decode(new Float32Array(16000), "Hetzner")).toThrow(/greedy/);
    expect(greedy.decode(new Float32Array(16000)).text).toBe("ok");
    expect(calls).toEqual([[]]);
  });
});

describe("the hotword vocabulary file two Workers share", () => {
  // The live Worker and the final-pass Worker can each write the same content-addressed file while
  // the other is creating its recognizer from it; sherpa-onnx exits the process on a torn file.
  test("a complete file already in place is never rewritten, so a reader never sees it truncated", () => {
    const d = dir();
    const path = writeBpeVocab(d, "\u2581Het -1\nzner -1\n");
    const past = new Date(Date.UTC(2020, 0, 1));
    utimesSync(path, past, past);
    expect(writeBpeVocab(d, "\u2581Het -1\nzner -1\n")).toBe(path);
    expect(statSync(path).mtimeMs).toBe(past.getTime());
    expect(readdirSync(d)).toEqual([path.slice(d.length + 1)]);
  });

  test("a file under the right name with the wrong bytes is replaced whole, leaving no temporary", () => {
    const d = dir();
    const path = writeBpeVocab(d, "\u2581Het -1\nzner -1\n");
    writeFileSync(path, "\u2581He");
    expect(writeBpeVocab(d, "\u2581Het -1\nzner -1\n")).toBe(path);
    expect(readFileSync(path, "utf8")).toBe("\u2581Het -1\nzner -1\n");
    expect(readdirSync(d)).toEqual([path.slice(d.length + 1)]);
  });
});
